  Y_{\nu_i} = \frac{4\pi m_b}{\rho} \left(\frac{k_\text{B}T}{hc}\right)^3
              F_2\left(\frac{\mu_{\nu_i}}{T}\right),
\end{equation}
where $m_b$ is the average baryon mass and $F_i(x)$ is the $i^\text{th}$ Fermi function.

\begin{align}
    P &=P_\mathrm{cold}(\rho)+P_\mathrm{th} \label{eq:P}\\
    \epsilon &=\epsilon_\mathrm{cold}(\rho)+\epsilon_\mathrm{th} \label{eq:Eps}
\end{align}
$P_\mathrm{cold}$ and $\epsilon_\mathrm{cold}$ are functions of the density $\rho$ only and are determined by the barotropic model. $\rho$ and $\epsilon$ are evolved by solving the hydrodynamic equations. The thermal specific energy is then defined by $\epsilon_\mathrm{th}=\epsilon-\epsilon_\mathrm{cold}(\rho)$.

From this the thermal part of the pressure $P_\mathrm{th}$ is obtained at a density $\rho$ adopting an ideal-gas like behavior
\begin{align}
    P_\mathrm{th}=(\Gamma_\mathrm{th}-1)\rho\epsilon_\mathrm{th}\label{eq:Pth}
\end{align}
where $\Gamma_\mathrm{th}$ is a chosen thermal ideal-gas index. In merger simulations, this value is usually assumed to be constant at all densities, even though microphysical EoS models show some variations~\cite{Constantinou2015}. For many models choosing $\Gamma_\mathrm{th}\approx1.75$ is a good compromise~\cite{Bauswein2010} and it is often chosen in merger simulations (see e.g.~\cite{Hotokezaka2013,Bernuzzi2015,Bauswein2019,Weih2019,Foucart2019,Ecker2020,Chaurasia2020,Blacker2020,Bauswein2020a,Bauswein2021,Liebling2021,Fujimoto2022,Palenzuela2022}.

Instead we pick a functional form that somewhat resembles the phase boundaries of the DD2F-SF models. For the onset boundary we use a hyperbola
\begin{align}
    \epsilon_\mathrm{on}(\rho)&=\frac{1}{a_\mathrm{on}\rho+b_\mathrm{on}}+c_\mathrm{on}~~ \forall \rho <\rho_\mathrm{on} \label{eq:ethonWeih}
\end{align}
where $\rho$ refers to the rest-mass density in geometric units with $\mathrm{G}=\mathrm{c}=1$. We choose two sets of parameters with this phase boundary. For the first set we pick $a_\mathrm{on}=10065.12$, $b_\mathrm{on}=3.420353$ and $c_\mathrm{on}=-0.083468$, we refer to this simulation as effPTlow simulation. For the second set we chose $a_\mathrm{on}=4065.12$, $b_\mathrm{on}=1.420353$ and $c_\mathrm{on}=-0.205015$. This leads to a weaker shift of the phase boundaries towards lower densities as our first set, we refer to this simulation as effPThigh simulation. This choice of parameters reproduces the correct onset density of the cold EoS $\rho_\mathrm{on,0}=2.085 \times \rho_\mathrm{nuc}$ in both cases. For the end of the coexistence phase we have $\rho_\mathrm{fin,0}=4.072 \times \rho_\mathrm{nuc}$ at zero temperature.

\begin{align}
    \frac{P_\mathrm{fin}(\epsilon_\mathrm{th})-P_\mathrm{on}(\epsilon_\mathrm{th})}{\rho_\mathrm{fin}(\epsilon_\mathrm{th})-\rho_\mathrm{on}(\epsilon_\mathrm{th})}=\frac{P_\mathrm{fin,0}-P_\mathrm{on,0}}{\rho_\mathrm{fin,0}-\rho_\mathrm{on,0}}~~\forall \epsilon_\mathrm{th}~.
\end{align}
We chose this approach to ensure that for a fixed $\epsilon_\mathrm{th}$ the pressures inferred by the effPT scheme never decreases with density.

\subsection{Simple thermal EoS model}
We consider a system in thermodynamic equilibrium with properties determined by a temperature $T$, a particle number $N$ and a volume $V$. The relevant thermodynamic potential is the free energy $F$
\begin{align}
    F=-PV+\mu N
\end{align}
with the pressure $P$ and the chemical potential $\mu$ defined as
\begin{align}
    P=-\left.\frac{\partial F}{\partial V}\right\vert_{T,N}~~~~  \mu=\left.\frac{\partial F}{\partial N}\right\vert_{T,V}~.
\end{align}
With the entropy $S$
\begin{align}
    S=-\left.\frac{\partial F}{\partial T}\right\vert_{V,N}
\end{align}
the internal energy $E$ of the system is given by
\begin{align}
    E=F+TS~.
\end{align}
It is useful to remove V and N as explicit variables and consider densities
\begin{align}
    n=\frac{N}{V},~~~~ 
    f=\frac{F}{V},~~~~ 
    e=\frac{E}{V},~~~~ 
    s=\frac{S}{V}~~~~ 
\end{align}
Then we have 
\begin{align}
    f&=-P+\mu n,~~~~ 
    P=n^2\left.\frac{\partial(f/n)}{\partial n}\right\vert_{T},~~~~
    \mu=\left.\frac{\partial f}{\partial n}\right\vert_{T}\\
    s&=-\left.\frac{\partial f}{\partial T}\right\vert_{n},~~~~
    e=f+Ts=Ts-P+\mu n
\end{align}
If we split the energy into a cold part $e_\mathrm{c}$ and a thermal part $e_\mathrm{th}$ we get
\begin{align}
    f=e_\mathrm{c}+e_\mathrm{th}-Ts=f_\mathrm{c}+f_\mathrm{th}
\end{align}
with 
\begin{align}
    f_\mathrm{c}=e_\mathrm{c},~~~~f_\mathrm{th}=e_\mathrm{th}-Ts~.
\end{align}
With this we can write $e_\mathrm{th}$ and the thermal pressure $P_\mathrm{th}$ as
\begin{align}
    P_\mathrm{th}=n\left.\frac{\partial f_\mathrm{th}}{\partial n}\right\vert_{T}-f_\mathrm{th},~~~~
    e_\mathrm{th}=f_\mathrm{th}-T\left.\frac{\partial f_\mathrm{th}}{\partial T}\right\vert_{n}
\end{align}
If we assume that the relation $P_\mathrm{th}=(\Gamma_\mathrm{th}-1)e_\mathrm{th}$ holds for the thermal contribution to an EoS we obtain
\begin{align}
    \Gamma_\mathrm{th}&=\frac{P_\mathrm{th}}{e_\mathrm{th}}+1=\frac{n \left.\frac{\partial f_\mathrm{th}}{\partial n}\right\vert_{T}-f_\mathrm{th} }{f_\mathrm{th}-T\left.\frac{\partial f_\mathrm{th}}{\partial n}\right\vert_{n}}+1\\
    &=\frac{n \left.\frac{\partial f_\mathrm{th}}{\partial n}\right\vert_{T}- T\left.\frac{\partial f_\mathrm{th}}{\partial T}\right\vert_{n}  }{f_\mathrm{th}-T\left.\frac{\partial f_\mathrm{th}}{\partial n}\right\vert_{n}}
\end{align}
This expression can be written as a partial differential equation for the thermal part of the free energy density $f_\mathrm{th}$
\begin{align}
    \Gamma_\mathrm{th}f_\mathrm{th}=n\left.\frac{\partial f_\mathrm{th}}{\partial n}\right\vert_{T}-(1-\Gamma_\mathrm{th})T\left.\frac{\partial f_\mathrm{th}}{\partial T}\right\vert_{n}.
\end{align}
A solution to this equation is given by
\begin{align}
    f_\mathrm{th}=Tn \left(a \ln \frac{n}{n_0}-b\ln \frac{T}{T_0}+c\right) \label{eq:fth}
\end{align}
with three dimensionless free parameters $a>0$, $b>0$ and $c$ and two scaling variables $n_0$ and $T_0$ to guarantee proper units in the arguments of the logarithmic functions.

