\begin{align}
    \mu_{h}(T)-\mu_{q}(T)=\int_{n_h(T)}^{n_q(T)}\frac{1}{n} \left.\frac{\partial P}{\partial n}\right\vert_{T} dn~.
\end{align}
Because $P=P_\mathrm{pt}(T)$ is constant with the particle density in the coexistence region the chemical potentials $\mu_{h}(T)$ and $\mu_{q}(T)$ at the borders of this region are identical $\mu_\mathrm{pt}(T)=\mu_{h}(T)=\mu_{q}(T)$ with $\mu_{h}(T)=\mu(T,n_{q}(T))$ and $\mu_{q}(T)=\mu(T,n_{q}(T))$.

If we write the free energy densities of both phases each as the sum of a $T=0$ component and a thermal contribution
\begin{align}
    f^h=e_\mathrm{c}^h+f_\mathrm{th}^h,~~~~
    f^q=e_\mathrm{c}^q+f_\mathrm{th}^q
\end{align}
and parametrize the thermal contributions according Eq.~\eqref{eq:fth} we get
\begin{align}
\begin{split}
    P_\mathrm{pt}(T)=&P_\mathrm{c}(n_h(T))+a_h Tn_h(T)\\
    =&P_\mathrm{c}(n_q(T))+a_q Tn_q(T)\label{eq:pth1}
\end{split}\\
\begin{split}
    \mu_\mathrm{th}(T)=&\mu_\mathrm{c}(n_h(T))+T(a_h\ln(n_h/n_0)- \\ &b_h\ln(T/T_0)+a_h+c_h)\\
    =&\mu_\mathrm{c}(n_q(T))+T(a_q\ln(n_q/n_0)- \\ &b_q\ln(T/T_0)+a_q+c_q)~. \label{eq:muth1}
\end{split}
\end{align}
These two equations fix the phase boundaries $n_h(T)$ and $n_q(T)$ at a given temperature.

If we write the free energy densities of both phases each as the sum of a $T=0$ component and a thermal contribution
\begin{align}
    f^h=e_\mathrm{c}^h+f_\mathrm{th}^h,~~~~
    f^q=e_\mathrm{c}^q+f_\mathrm{th}^q
\end{align}
and parametrize the thermal contributions according Eq.~\eqref{eq:fth} we get
\begin{align}
\begin{split}
    P_\mathrm{pt}(T)=&P_\mathrm{c}(n_h(T))+a_h Tn_h(T)\\
    =&P_\mathrm{c}(n_q(T))+a_q Tn_q(T)\label{eq:pth1}
\end{split}\\
\begin{split}
    \mu_\mathrm{th}(T)=&\mu_\mathrm{c}(n_h(T))+T(a_h\ln(n_h/n_0)- \\ &b_h\ln(T/T_0)+a_h+c_h)\\
    =&\mu_\mathrm{c}(n_q(T))+T(a_q\ln(n_q/n_0)- \\ &b_q\ln(T/T_0)+a_q+c_q)~. \label{eq:muth1}
\end{split}
\end{align}
These two equations fix the phase boundaries $n_h(T)$ and $n_q(T)$ at a given temperature.

The energy densities at the borders of the coexistence region are given by
\begin{align}
    e(T,n_h(T))=e_{c,h}(n_h(T))+b_h Tn_h(T)\label{eq:eth1}\\
    e(T,n_q(T))=e_{c,q}(n_q(T))+b_q Tn_q(T)\label{eq:eth2}
\end{align}
where $e_{c,h}$ and $e_{c,q}$ are the energy densities of both phases at $T=0$.

As an example we consider the following simple two-phase model. We assume a cold polytropic EoS representing the hadronic regime at lower densities and another cold polytropic EoS describing deconfined quark matter at higher densities. Both EoSs can hence be described by
\begin{align}
    p_\mathrm{c}&=Kn^{\Gamma}\\
    \mu_\mathrm{c}&=\frac{K\Gamma}{\Gamma-1}n^{\Gamma-1}+E_0~.
\end{align}
We pick $\Gamma=1.8$ for the low density phase and $\Gamma=2.5$ for the high density phase. We also require that the coexistence phase lies between $n_\mathrm{on}=0.3~\mathrm{fm}^{-3}$ and $n_\mathrm{fin}=0.5~\mathrm{fm}^{-3}$, has a pressure of $p_\mathrm{pt}=21~\mathrm{MeV/fm}^{3}$ and a chemical potential of $\mu_\mathrm{pt}=1005~\mathrm{MeV}$. This choice of $p_\mathrm{pt}$ and $\mu_\mathrm{pt}$ at $n_\mathrm{on}$ and $n_\mathrm{fin}$ fixes the parameters $K$ and $E_0$ in both cold phases.

We find that in the density range relevant for constructing the phase transition between $0.1\times \rho_\mathrm{nuc}$ and $3.5\times \rho_\mathrm{nuc}$ the DD2F EoS can be approximated well by a piecewise polytropic EoS with two segments. In such a model the pressure, chemical potential and energy density of each segment are given by
\begin{align}
    P&=K_{i}n^{\Gamma_{i}} \label{eq:Ppp}\\
    \mu&=\frac{K_{i}\Gamma_{i}}{\Gamma_{i}-1}n^{\Gamma_{i}-1}+E_{0,i}\label{eq:mupp}\\
    e&=\frac{K_{i}}{\Gamma_{i}-1}n^{\Gamma_{i}}+E_{0,i}n\label{eq:epp}
\end{align}
with $i=1,2$. We perform a least squares fit to the tabulated pressure of the DD2F EoS with Eq.~\eqref{eq:Ppp} in the aforementioned density range. During this fit we pick the parameters $K_{2}$ and $E_{0,2}$ to recover $P$ and $\mu$ of the DD2F EoS at $n=3.5\times \rho_\mathrm{nuc}$. This ensures that we recreate the true onset density of the DD2F-SF-7 EoS at $T=0$. The parameters $K_{1}$ and $E_{0,1}$ are fixed by requiring continuous $P$ and $e$. Hence we are left with fitting the parameters $\Gamma_{1,2}$ and the density $n_1$ where we switch from one segment to the other.

For the cold quark phase a piecewise polytropic model is not well suited because the pressure is expected to become negative at low densities due to quark confinement. Such a behavior cannot be achieved in a polytropic approach. Instead we describe the quark phase using the bag model of~\cite{Alford2005}. In this model the grandcanonical potential density $\Omega$ is given by
\begin{align}
    \Omega=-\left(\frac{3}{4\pi^{2}}a_4\mu_q^4+\frac{3}{4\pi^{2}}a_2\mu_q^2+B_\mathrm{eff}\right)\frac{1}{(\hbar c)^{3}}~.
\end{align}

From this we obtain
\begin{align}
    P_q&=\left(\frac{3}{4\pi^{2}}a_4\mu_q^4-\frac{3}{4\pi^{2}}a_2\mu_q^2-B_\mathrm{eff}\label{eq:pbag}\right)\frac{1}{(\hbar c)^{3}}\\
    n_q&=\left(\frac{3}{\pi^{2}}a_4\mu_q^3-\frac{3}{2\pi^2}a_2\mu_q\right)\frac{1}{(\hbar c)^{3}}  \label{eq:nbag}\\
    e_q&=\left(\frac{9}{4\pi^2}a_4\mu_q^4-\frac{3}{4\pi^2}a_2\mu_q^2+B_\mathrm{eff}\right)\frac{1}{(\hbar c)^{3}}~. \label{eq:ebag}
\end{align}
Note that here $\mu_q$ and $n_q$ refer to the quark chemical potential and number density, respectively. We assume $3\mu_q=\mu$ and $n_q=3n$.

