 f(k, \pm \mu_i) = \frac{1}{e^{(E_i(k) \mp \mu_i)/T} +1}.
\end{eqnarray}
The degeneracy factor $g_i = 2$ for electrons and  $g_i = 6$ for each quark flavor.

The total entropy density is given by
\begin{equation}
\label{tot_entropy}
  s = \sum_{i=u,d,s,e} s_i\,
\end{equation}
and can be calculated using the ideal Fermi gas approximation for each fermionic species \cite{Fetter-Walecka:book1971}:
\begin{eqnarray}
s_i (T,\mu_i) &=& - \frac{g_i}{2\pi^2} \int_0^\infty k^2 dk
\left[ f (k,\mu_i) \mathrm{ln} f (k,\mu_i) \right.
\nonumber \\
&+& ( 1 - f(k,\mu_i)) \mathrm{ln}(1-f(k,\mu_i))
\nonumber\\
&+&
f(k,-\mu_i) \mathrm{ln} f(k,-\mu_i)
\nonumber \\
&+& \left. ( 1 - f (k,-\mu_i)) \mathrm{ln}(1-f (k,-\mu_i))
\right] \, .
\label{entropy_f}
\end{eqnarray}

