                 & = \sum_{j=1}^4 \left[ h_{j,+}(\boldsymbol{\theta},t) - i h_{j,\times} (\boldsymbol{\theta},t) \right],
                 \label{Eq:anmodel}
\end{align}
with the individual ($+$) polarization components written as
\begin{equation}
    h_{j,+}(\boldsymbol{\theta}, t) = A_j \exp\left[ -\frac{t}{T_j}\right] \cos\left[2\pi f_j t(1+a_j t) + \psi_j\right].
    \label{Eq:analytic}
\end{equation}

For the primary post-merger frequency, a useful empirical relation for  $f_{\mathrm{peak}}$ was derived in \cite{VSB2020}:
\begin{equation}\label{eq:peak}
f_\mathrm{peak}M_\mathrm{chirp} =  1.392 - 0.108 M_\mathrm{chirp}+51.70 \tilde{\Lambda}^{-1/2},
\end{equation}
where $M_\mathrm{chirp} = (M_A M_B)^{3 / 5}/(M_A+M_B)^{1 / 5}$, is the chirp mass of the binary, with $M_A, M_B$ being the individual masses and 
\begin{equation}
\tilde{\Lambda}=\frac{16}{13} \frac{\left(M_A+12 M_B\right) M_A^4 \Lambda_A+\left(M_B+12 M_A\right) M_B^4 \Lambda_B}{\left(M_A+M_B\right)^5}
\end{equation}
is the mass-weighted tidal deformability, with $\Lambda_A, \Lambda_B$ being the individual dimensionless tidal deformabilities, respectively. This empirical relation has a maximum residual of $0.302$kHz and $R^2=0.985$. It was constructed using a large set of both equal-mass and un-equal-mass models and is thus relatively insensitive to the mass ratio $q$.

For the primary post-merger frequency, a useful empirical relation for  $f_{\mathrm{peak}}$ was derived in \cite{VSB2020}:
\begin{equation}\label{eq:peak}
f_\mathrm{peak}M_\mathrm{chirp} =  1.392 - 0.108 M_\mathrm{chirp}+51.70 \tilde{\Lambda}^{-1/2},
\end{equation}
where $M_\mathrm{chirp} = (M_A M_B)^{3 / 5}/(M_A+M_B)^{1 / 5}$, is the chirp mass of the binary, with $M_A, M_B$ being the individual masses and 
\begin{equation}
\tilde{\Lambda}=\frac{16}{13} \frac{\left(M_A+12 M_B\right) M_A^4 \Lambda_A+\left(M_B+12 M_A\right) M_B^4 \Lambda_B}{\left(M_A+M_B\right)^5}
\end{equation}
is the mass-weighted tidal deformability, with $\Lambda_A, \Lambda_B$ being the individual dimensionless tidal deformabilities, respectively. This empirical relation has a maximum residual of $0.302$kHz and $R^2=0.985$. It was constructed using a large set of both equal-mass and un-equal-mass models and is thus relatively insensitive to the mass ratio $q$.

We use the particular empirical relation in Eq. (\ref{eq:peak}), because both $M_\mathrm{chirp}$ and $\tilde{\Lambda}$ can be constrained by GW observations in the inspiral phase of a BNS merger. Using the data in Table II of \cite{VSB2020} and a standard Levenberg-Marquardt nonlinear least-squares minimization algorithm, we construct similar empirical relations for two additional post-merger peaks:
\begin{equation}\label{eq:quasiradial}
    f_\mathrm{2-0}M_\mathrm{chirp} =  0.558 - 0.406 M_\mathrm{chirp}+48.696 \tilde{\Lambda}^{-1/2},
\end{equation}
with a maximum residual of $0.362$kHz and $R^2=0.941$, and
\begin{equation}\label{eq:spiral}
f_\mathrm{spiral}M_\mathrm{chirp} =  1.2 - 0.442 M_\mathrm{chirp}+45.819 \tilde{\Lambda}^{-1/2},
\end{equation}
with a maximum residual of $0.461$kHz and $R^2=0.944$.
Fig.~\ref{fig:empirical-surfaces} displays all three empirical relations in Eqs. (\ref{eq:peak}), (\ref{eq:spiral}) and (\ref{eq:quasiradial}) as two-dimensional, non-intersecting surfaces.

