\begin{align}
	p(R_{1.2}, \ldots R_{1.8}, \vec{\Upsilon}|{\cal D})
			& = p(\vec{\Upsilon}) \prod_{i=1}^{4} \frac{p(d_i|R_{1.X_i})p(R_{1.X_i}|\vec{\Upsilon})}{p(d_i)},
\label{eq:hbi2}
\end{align}
where we consider $R_{1.X_i}$ with $X_i \in [2, 4, 6, 8]$ and ${\bf {\cal D}} \coloneqq \{d_1, d_2, d_3, d_4\}$. The likelihoods $p(d_i|R_{1.X_i})$ are the posteriors, $p(R_{1.X_i}|{\mathbf D})$, obtained from Eq.  (\ref{eq:finalpost_propto}).

